        .get("CATEGORIES")
        .into_iter()
        .flatten()
        .map(|p| {
            // Split raw TEXT before unescaping so escaped commas stay in one value.
            let mut escaped = false;
            p.value
                .split(|character| {
                    if escaped {
                        escaped = false;
                        return false;
                    }
                    if character == '\\' {
                        escaped = true;
                        return false;
                    }
                    character == ','
