 51	        .await
 52	        .unwrap();
 53	
 54	    assert_eq!(result.event_ids.len(), 2);
 55	    assert_eq!(result.exception_count, 3);
 56	    let event_count: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM events")
 57	        .fetch_one(&pool)
 58	        .await
 59	        .unwrap();
 60	    let exception_count: i64 =
 61	        sqlx::query_scalar("SELECT COUNT(*) FROM event_recurrence_exceptions")
 62	            .fetch_one(&pool)
 63	            .await
 64	            .unwrap();
 65	    let audits: Vec<String> =
 66	        sqlx::query_scalar("SELECT action FROM audit_log WHERE target_type = 'event' ORDER BY id")
 67	            .fetch_all(&pool)
 68	            .await
 69	            .unwrap();
 70	    let external_count: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM external_event_mapping")
 71	        .fetch_one(&pool)
 72	        .await
 73	        .unwrap();
 74	    let caldav_changes: Vec<i64> = sqlx::query_scalar(
 75	        "SELECT event_id FROM caldav_event_changes WHERE change_type = 'created' ORDER BY id",
 76	    )
 77	    .fetch_all(&pool)
 78	    .await
 79	    .unwrap();
 80	    assert_eq!(event_count, 2);
 81	    assert_eq!(exception_count, 3);
 82	    assert_eq!(audits, vec!["event.series.create", "event.series.create"]);
 83	    assert_eq!(external_count, 0);
 84	    let mut expected_changes = result.event_ids.clone();
 85	    expected_changes.sort_unstable();
 86	    let mut actual_changes = caldav_changes;
