260	#[derive(Clone)]
261	struct Property {
262	    name: String,
263	    params: HashMap<String, String>,
264	    value: String,
265	    raw_len: usize,
266	}
267	fn unfold(input: &str) -> Result<Vec<String>, IcsParseError> {
268	    let mut lines: Vec<String> = Vec::new();
269	    for raw in input.lines() {
270	        let line = raw.strip_suffix('\r').unwrap_or(raw);
271	        if line.starts_with(' ') || line.starts_with('\t') {
272	            lines
273	                .last_mut()
274	                .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?
275	                .push_str(&line[1..]);
276	        } else if !line.is_empty() {
277	            lines.push(line.to_owned());
278	        }
279	    }
280	    if lines.is_empty() {
281	        return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
282	    }
283	    Ok(lines)
284	}
285	fn property(line: &str) -> Result<Property, IcsParseError> {
286	    // Delimiters inside quoted parameter values are data (RFC 5545 §3.1).
287	    let mut quoted = false;
288	    let separator = line
289	        .char_indices()
290	        .find_map(|(index, character)| {
291	            if character == '"' {
292	                quoted = !quoted;
293	            }
294	            (character == ':' && !quoted).then_some(index)
295	        })
296	        .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
297	    let (left, remainder) = line.split_at(separator);
298	    let value = &remainder[1..];
299	    quoted = false;
300	    let mut parts = left.split(|character| {
301	        if character == '"' {
302	            quoted = !quoted;
303	        }
304	        character == ';' && !quoted
305	    });
306	    let name = parts.next().unwrap().to_ascii_uppercase();
307	    if name.is_empty() || !name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
308	        return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
309	    }
310	    let mut params = HashMap::new();
311	    for part in parts {
312	        let (key, value) = part
313	            .split_once('=')
314	            .ok_or(IcsParseError::new(IcsParseErrorCode::Malformed))?;
315	        if params
316	            .insert(key.to_ascii_uppercase(), value.trim_matches('"').to_owned())
317	            .is_some()
318	        {
319	            return Err(IcsParseError::new(IcsParseErrorCode::Malformed));
320	        }
321	    }
322	    Ok(Property {
323	        name,
324	        params,
325	        value: value.to_owned(),
326	        raw_len: line.len(),
327	    })
328	}
