501	/// The bounded set of X-properties that are preserved. Any other X-property is
502	/// ignored by the parser (it is neither preserved nor rejected here); the DAV
503	/// layer enforces the write-time policy.
504	const ALLOWED_X_PROPERTIES: &[&str] = &[
505	    "X-APPLE-CEVENT-CATEGORY",
506	    "X-APPLE-STRUCTURED-LOCATION",
507	    "X-APPLE-FALLBACK-ALARM-UID",
508	];
509	
510	/// Collect the allowlisted X-properties from a VEVENT's properties, in
511	/// document order. Non-allowlisted X-properties are ignored.
512	fn collect_x_properties(
513	    properties: &[Property],
514	    limits: IcsParserLimits,
515	) -> Result<Vec<NormalizedXProperty>, IcsParseError> {
516	    let mut out = Vec::new();
517	    for property in properties {
518	        if !property.name.starts_with("X-") {
519	            continue;
520	        }
521	        if !ALLOWED_X_PROPERTIES.contains(&property.name.as_str()) {
522	            continue;
523	        }
524	        let value = text(property, limits)?;
525	        out.push(NormalizedXProperty {
526	            name: property.name.clone(),
527	            value,
528	        });
529	    }
530	    Ok(out)
531	}
532	
533	/// Normalize the VALARM subcomponents of a VEVENT into `NormalizedAlarm`s.
534	///
535	/// Only `DISPLAY` and `AUDIO` alarms with a `TRIGGER` are preserved. Alarms
536	/// with other actions (e.g. `EMAIL`) or without a trigger are dropped, so the
537	/// preserved set is bounded and deterministic.
538	fn normalize_alarms(
539	    alarms: &[Vec<Property>],
540	    limits: IcsParserLimits,
541	) -> Result<Vec<NormalizedAlarm>, IcsParseError> {
542	    let mut out = Vec::with_capacity(alarms.len());
543	    for alarm in alarms {
544	        let mut action = None;
545	        let mut trigger = None;
546	        let mut description = None;
547	        for p in alarm {
548	            match p.name.as_str() {
549	                "ACTION" => action = Some(p.value.to_ascii_uppercase()),
550	                "TRIGGER" => trigger = Some(p.value.clone()),
551	                "DESCRIPTION" => description = Some(text(p, limits)?),
552	                _ => {}
553	            }
554	        }
555	        let Some(action) = action else {
556	            continue;
557	        };
558	        if !matches!(action.as_str(), "DISPLAY" | "AUDIO") {
559	            continue;
560	        }
561	        let Some(trigger) = trigger else {
562	            continue;
563	        };
564	        out.push(NormalizedAlarm {
565	            action,
566	            trigger,
567	            description,
568	        });
569	    }
570	    Ok(out)
571	}
572	fn text(p: &Property, limits: IcsParserLimits) -> Result<String, IcsParseError> {
573	    if p.value.len() > limits.max_text_bytes {
574	        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
575	    }
576	    let mut out = String::new();
577	    let mut escaped = false;
578	    for c in p.value.chars() {
579	        if escaped {
580	            out.push(match c {
581	                'n' | 'N' => '\n',
582	                '\\' => '\\',
583	                ',' => ',',
584	                ';' => ';',
585	                _ => return Err(IcsParseError::new(IcsParseErrorCode::Malformed)),
586	            });
587	            escaped = false;
588	        } else if c == '\\' {
589	            escaped = true;
590	        } else {
591	            out.push(c);
592	        }
593	    }
594	    if escaped || out.len() > limits.max_text_bytes {
595	        return Err(IcsParseError::new(IcsParseErrorCode::LimitExceeded));
596	    }
597	    Ok(out)
598	}
599	fn date_value(p: &Property) -> Result<NormalizedDateValue, IcsParseError> {
600	    if p.params.get("VALUE").is_some_and(|v| v != "DATE") {
601	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
602	    }
603	    if p.params.get("VALUE").is_some_and(|v| v == "DATE") || p.value.len() == 8 {
604	        return NaiveDate::parse_from_str(&p.value, "%Y%m%d")
605	            .map(NormalizedDateValue::AllDay)
606	            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent));
607	    }
608	    let naive = NaiveDateTime::parse_from_str(p.value.trim_end_matches('Z'), "%Y%m%dT%H%M%S")
609	        .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?;
610	    let value = if p.value.ends_with('Z') {
611	        naive.and_utc()
612	    } else if let Some(tz) = p.params.get("TZID") {
613	        let tz: Tz = tz
614	            .parse()
615	            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?;
616	        match tz.from_local_datetime(&naive) {
617	            LocalResult::Single(v) => v.with_timezone(&Utc),
618	            _ => return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent)),
619	        }
620	    } else {
621	        naive.and_utc()
622	    };
623	    Ok(NormalizedDateValue::Timed(value))
624	}
625	fn timing(
626	    start: NormalizedDateValue,
627	    end: Option<NormalizedDateValue>,
628	    duration: Option<Duration>,
629	    timezone: Option<String>,
630	) -> Result<NormalizedTiming, IcsParseError> {
631	    match (start, end, duration) {
632	        (NormalizedDateValue::Timed(s), Some(NormalizedDateValue::Timed(e)), None) if e > s => {
633	            Ok(NormalizedTiming::Timed {
634	                starts_at: s,
635	                ends_at: e,
636	                timezone,
637	            })
638	        }
639	        (NormalizedDateValue::Timed(s), None, Some(d)) if d > Duration::zero() => {
640	            Ok(NormalizedTiming::Timed {
641	                starts_at: s,
642	                ends_at: s + d,
643	                timezone,
644	            })
645	        }
646	        (NormalizedDateValue::AllDay(s), Some(NormalizedDateValue::AllDay(e)), None)
647	            if e > s && timezone.is_none() =>
648	        {
649	            Ok(NormalizedTiming::AllDay {
650	                start_date: s,
651	                end_date: e,
652	            })
653	        }
654	        (NormalizedDateValue::AllDay(s), None, Some(d))
655	            if d > Duration::zero() && d.num_seconds() % 86_400 == 0 && timezone.is_none() =>
656	        {
657	            Ok(NormalizedTiming::AllDay {
658	                start_date: s,
659	                end_date: s
660	                    .checked_add_signed(d)
661	                    .ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?,
662	            })
663	        }
664	        _ => Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent)),
665	    }
666	}
667	fn parse_duration(value: &str) -> Result<Duration, IcsParseError> {
668	    if !value.starts_with('P') || value.contains('-') {
669	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
670	    }
671	    let mut seconds = 0_i64;
672	    let mut n = String::new();
673	    for ch in value[1..].chars() {
674	        if ch.is_ascii_digit() {
675	            n.push(ch);
676	            continue;
677	        }
678	        if ch == 'T' {
679	            continue;
680	        }
681	        let number: i64 = n
682	            .parse()
683	            .map_err(|_| IcsParseError::new(IcsParseErrorCode::InvalidEvent))?;
684	        n.clear();
685	        seconds = seconds
686	            .checked_add(match ch {
687	                'W' => number * 604_800,
688	                'D' => number * 86_400,
689	                'H' => number * 3_600,
690	                'M' => number * 60,
691	                'S' => number,
692	                _ => return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent)),
693	            })
694	            .ok_or(IcsParseError::new(IcsParseErrorCode::InvalidEvent))?;
695	    }
696	    if !n.is_empty() || seconds <= 0 {
697	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
698	    }
699	    Ok(Duration::seconds(seconds))
700	}
701	fn utc_datetime(p: &Property) -> Result<DateTime<Utc>, IcsParseError> {
702	    if !p.value.ends_with('Z') || p.params.contains_key("TZID") {
703	        return Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent));
704	    }
705	    match date_value(p)? {
706	        NormalizedDateValue::Timed(v) => Ok(v),
707	        _ => Err(IcsParseError::new(IcsParseErrorCode::InvalidEvent)),
708	    }
709	}
710	fn same_kind(value: &NormalizedDateValue, timing: &NormalizedTiming) -> bool {
711	    matches!(
712	        (value, timing),
713	        (
714	            NormalizedDateValue::Timed(_),
715	            NormalizedTiming::Timed { .. }
716	        ) | (
717	            NormalizedDateValue::AllDay(_),
718	            NormalizedTiming::AllDay { .. }
719	        )
720	    )
721	}
